// Regression test for: Product search is case-sensitive
// Generated by WebProbe gen-tests from 2026-11-11T19-26-42-760Z, report #3.
// It failed with the bug and passed on the clean site. Edit freely; promote-tests won't overwrite it.

import { test, expect } from "@playwright/test";

test("product search matches regardless of letter case", async ({ page }) => {
  const errors: string[] = [];
  page.on("pageerror", (err) => errors.push(err.message));

  await page.goto("/");
  const search = page.getByRole("searchbox", { name: "Search products" });

  await search.fill("lamp");
  await expect(page.getByRole("link", { name: "Desk Lamp" })).toBeVisible();
  await expect(page.getByText(/No products match/)).toHaveCount(0);

  await search.fill("Lamp");
  await expect(page.getByRole("link", { name: "Desk Lamp" })).toBeVisible();

  expect(errors).toEqual([]);
});
